#!/usr/bin/env tsx
/**
 * Generate a side-by-side readability comparison.
 *
 * The project's premise is that the ScriptType form is easier to write and reason about
 * than the type-level original. That claim should be checkable rather than asserted, so
 * this emits the original type and its ScriptType form next to each other, with the
 * TypeScript the latter compiles back to.
 */
import fs from 'node:fs';
import path from 'node:path';
import { decompileFile } from './decompile.js';
import { compile } from './compile.js';
import { extractType } from './extract.js';
import { REPO_ROOT } from './corpus.js';
/** Types chosen to span the constructs that make type-level code hard to read. */
const PICKS = [
    {
        file: '01-type-level-programming/ts-toolbelt/sources/String/Split.ts',
        type: '__Split',
        why: 'A loop written as recursion. Recovery restores the loop.',
    },
    {
        file: '01-type-level-programming/ts-pattern/src/types/helpers.ts',
        type: 'Iterator',
        why: 'Loop-until-condition: recursion in the false branch.',
    },
    {
        file: '04-query-builders-orm/kysely/src/parser/select-parser.ts',
        type: 'ExtractTypeFromStringSelectExpression',
        why: 'Six-deep nested conditionals become flat early returns.',
    },
    {
        file: '04-query-builders-orm/kysely/src/util/type-utils.ts',
        type: 'AnyColumn',
        why: 'A mapped type becomes a for-in loop.',
    },
    {
        file: '01-type-level-programming/type-fest/source/trim.d.ts',
        type: 'Trim',
        why: 'Small composition, for a case where the original is already clear.',
    },
    {
        file: '04-query-builders-orm/kysely/src/util/type-utils.ts',
        type: 'DrainOuterGeneric',
        why: "kysely's instantiation-depth trick, exposed as defer().",
    },
];
function lineCount(s) {
    return s.trim().split('\n').length;
}
const out = [
    '# Is ScriptType actually easier to read?',
    '',
    'The project only earns its keep if the ScriptType form is easier to write and reason',
    'about than the type-level original. That is a claim about readability, so it is put',
    'side by side here rather than asserted. Every pair below is generated by the',
    'decompiler and verified to recompile to a type identical to the original.',
    '',
    'Regenerate with `npx tsx src/dx-report.ts`.',
    '',
    '## What actually gets easier',
    '',
    '**Control flow becomes linear.** A conditional type nests: each `? :` buries the next',
    'case one level deeper, so understanding the last branch means holding all the earlier',
    'ones in your head. Statements with early `return` put the cases side by side instead.',
    '',
    '**Loops stop being recursion.** A tail-recursive alias with an accumulator parameter',
    'is a `while` loop that has been hand-converted, including the manual threading of the',
    'accumulator through every call. Recovering the loop removes that bookkeeping.',
    '',
    '**Intermediate values get names.** `const` gives a name to a subexpression; a',
    'conditional type has to either repeat it or introduce an `extends infer` binding whose',
    'purpose is invisible.',
    '',
    '**What does not get easier.** Patterns are still patterns: `matches<...>` with',
    '`Hole<\'N\'>` is a little more verbose than `extends ... infer N`. Where the original is',
    'already a one-liner, ScriptType is longer and there is nothing to gain — the last',
    'example below is deliberately one of those.',
    '',
];
let shown = 0;
for (const pick of PICKS) {
    const abs = path.join(REPO_ROOT, pick.file);
    if (!fs.existsSync(abs))
        continue;
    const text = fs.readFileSync(abs, 'utf8');
    const entries = decompileFile(abs, text);
    const entry = entries.find((e) => e.name === pick.type);
    let original;
    try {
        const ex = extractType(abs, pick.type);
        original = ex.parts[ex.parts.length - 1].text;
    }
    catch {
        continue;
    }
    // Non-generic aliases are not decompiled; show the original alone.
    let st = '';
    let emitted = '';
    if (entry) {
        st = entry.result.source.replace(/^\/\* @scripttype[^\n]*\n/, '').trim();
        try {
            emitted = compile(entry.result.source, { includePrelude: false }).code.trim();
        }
        catch (e) {
            emitted = `// did not compile: ${e.message}`;
        }
    }
    if (!st)
        continue;
    shown++;
    out.push(`## ${pick.type}`);
    out.push('');
    out.push(`\`${pick.file}\``);
    out.push('');
    out.push(pick.why);
    out.push('');
    out.push(`**Original TypeScript** (${lineCount(original)} lines)`);
    out.push('');
    out.push('```ts');
    out.push(original.trim());
    out.push('```');
    out.push('');
    out.push(`**ScriptType** (${lineCount(st)} lines)`);
    out.push('');
    out.push('```ts');
    out.push(st);
    out.push('```');
    out.push('');
    out.push('**Compiles back to**');
    out.push('');
    out.push('```ts');
    out.push(emitted);
    out.push('```');
    out.push('');
}
const dest = path.join(REPO_ROOT, 'DX.md');
fs.writeFileSync(dest, out.join('\n'));
console.log(`wrote ${dest} with ${shown} comparisons`);
